    /// Render a line string.
    pub(super) fn render_line_string(&self, coords: &[(f64, f64)]) -> String {
        if coords.is_empty() {
            return String::new();
        }

        let d = self.config.digits;
        let mut path = String::with_capacity(coords.len() * 24);
        let mut prev_lon: Option<f64> = None;
        let mut need_move = true;

        for &(lon, lat) in coords.iter() {
            // Pre-clip: skip points outside the projection's clip angle
            if !self.projection.is_visible(lon, lat) {
                prev_lon = None;
                need_move = true;
                continue;
            }

            let (x, y) = self.projection.project(lon, lat);

            // Check if coordinates are valid
            if !x.is_finite() || !y.is_finite() {
                prev_lon = None;
                need_move = true;
                continue;
            }

            // Detect antimeridian crossing: if longitude jumps > 180 degrees
            let crosses_antimeridian = if let Some(prev) = prev_lon {
                (lon - prev).abs() > 180.0
            } else {
                false
            };

            if need_move || crosses_antimeridian {
                write!(&mut path, "M{:.d$},{:.d$}", x, y, d = d).unwrap();
                need_move = false;
            } else {
                write!(&mut path, "L{:.d$},{:.d$}", x, y, d = d).unwrap();
            }

            prev_lon = Some(lon);
        }

        path
    }

