    /// Render a polygon.
    pub(super) fn render_polygon(&self, rings: &[Vec<(f64, f64)>]) -> String {
        if rings.is_empty() {
            return String::new();
        }

        let d = self.config.digits;
        let mut path = String::with_capacity(rings.iter().map(|r| r.len()).sum::<usize>() * 24);

        for ring in rings {
            if ring.is_empty() {
                continue;
            }

            let mut prev_lon: Option<f64> = None;
            let mut ring_started = false;

            for &(lon, lat) in ring.iter() {
                // Pre-clip: skip points outside the projection's clip angle
                if !self.projection.is_visible(lon, lat) {
                    prev_lon = None;
                    if ring_started {
                        path.push('Z');
                        ring_started = false;
                    }
                    continue;
                }

                let (x, y) = self.projection.project(lon, lat);

                // Check if coordinates are valid
                if !x.is_finite() || !y.is_finite() {
                    prev_lon = None;
                    if ring_started {
                        path.push('Z');
                        ring_started = false;
                    }
                    continue;
                }

                // Detect antimeridian crossing: if longitude jumps > 180 degrees
                let crosses_antimeridian = if let Some(prev) = prev_lon {
                    (lon - prev).abs() > 180.0
                } else {
                    false
                };

                if !ring_started || crosses_antimeridian {
                    // Close previous segment if we're breaking due to antimeridian
                    if ring_started && crosses_antimeridian {
                        path.push('Z');
                    }
                    write!(&mut path, "M{:.d$},{:.d$}", x, y, d = d).unwrap();
                    ring_started = true;
                } else {
                    write!(&mut path, "L{:.d$},{:.d$}", x, y, d = d).unwrap();
                }

                prev_lon = Some(lon);
            }

            // Close the ring
            if ring_started {
                path.push('Z');
            }
        }

        path
    }

